@once
@push('styles')
<style>
.daily-review-pagination{display:flex!important;align-items:center;justify-content:space-between;gap:14px;min-height:62px;padding:13px 17px!important;border-top:1px solid #dfe9ef!important;background:linear-gradient(180deg,#fbfdfe,#f5f9fb)!important;color:#6a8191}.daily-review-pagination>.text-muted{display:flex;align-items:center;min-height:34px;color:#667f90!important;font-size:13px}.daily-review-pagination>.text-muted:before{content:"\f03a";display:inline-flex;width:30px;height:30px;align-items:center;justify-content:center;margin-right:8px;border-radius:8px;background:#e6f2f9;color:#2d86b5;font-family:FontAwesome}.daily-review-pagination .pagination{display:flex;align-items:center;gap:5px;margin:0!important;padding:0;white-space:nowrap}.daily-review-pagination .pagination>li{display:block}.daily-review-pagination .pagination>li>a,.daily-review-pagination .pagination>li>span{display:flex;min-width:35px;height:35px;align-items:center;justify-content:center;padding:0 10px;border:1px solid #d4e2ea!important;border-radius:7px!important;background:#fff;color:#397b9f;font-weight:600;line-height:1;box-shadow:0 2px 5px rgba(42,83,108,.06);transition:.15s}.daily-review-pagination .pagination>li>a:hover{border-color:#3d97c5!important;background:#eef8fd;color:#1d719d;transform:translateY(-1px)}.daily-review-pagination .pagination>.active>a,.daily-review-pagination .pagination>.active>span{border-color:#2e88b8!important;background:linear-gradient(135deg,#3c9dcc,#247cac)!important;color:#fff!important;box-shadow:0 4px 10px rgba(44,134,182,.24)}.daily-review-pagination .pagination>.disabled>span,.daily-review-pagination .pagination>.disabled>a{border-color:#e2e8ec!important;background:#f1f4f6!important;color:#a7b4bd!important;box-shadow:none}.daily-review-pagination .pull-right{float:none!important;margin-left:auto}.daily-review-pagination.is-links-only{justify-content:flex-end}.daily-review-pagination.is-links-only:before{content:"分页导航";margin-right:auto;color:#6c8292;font-size:13px}.daily-review-pagination.is-links-only:after{content:"可使用上一页、页码和下一页切换";order:-1;margin-right:8px;color:#91a0aa;font-size:11px}@media(max-width:767px){.daily-review-pagination{align-items:flex-start;flex-direction:column}.daily-review-pagination .pull-right,.daily-review-pagination .pagination{max-width:100%;margin-left:0!important;overflow-x:auto;padding-bottom:3px}.daily-review-pagination.is-links-only:after{display:none}}
</style>
@endpush
@push('scripts')
<script>
(function(){document.querySelectorAll('.content .box-footer').forEach(function(footer){var pagination=footer.querySelector('.pagination');if(!pagination)return;footer.classList.add('daily-review-pagination');var directText=Array.prototype.some.call(footer.childNodes,function(node){return node.nodeType===3&&node.textContent.trim()!=='';});if(!footer.querySelector('.text-muted')&&!directText)footer.classList.add('is-links-only');});})();
</script>
@endpush
@endonce
